L000033	\title{A Kapitza Pendulum Route to Supercurrent Tunnel Diodes}
L000034	
L000035	
L000036	
L000037	\author{Yuriy Yerin}
L000038	\affiliation{Istituto di Struttura della Materia of the National Research Council, via Salaria Km 29.3, I-00016 Monterotondo Stazione, Italy}
