L000378	This Supplemental Material presents the detailed reduction of the single- and double-loop SQUID models to the effective parametrically driven pendulum equation, together with the derivation of the Kapitza-averaged current-phase relation and diode efficiency.
L000379	
L000380	\section{Reduction of a gated single-loop dc SQUID at zero applied flux to an Effective Parametrically Driven Pendulum}
L000381	\label{sec:supp_singleloop_gate}
L000382	
L000383	In this section we derive the effective phase equation of motion
L000384	\begin{equation}
L000385	\ddot x + \beta \dot x
L000386	+ \big[i_{\mathrm{dc}}+i_{\mathrm{ac}}\cos(\omega t)\big]\sin x
L000387	+ i_{c,t} \sin(x+\phi)
L000388	= \frac{1}{2} i_b ,
L000389	\label{eq:EOM_supp}
L000390	\end{equation}
L000391	starting from the standard RCSJ description of a single-loop dc SQUID
L000392	(two Josephson elements in parallel forming a superconducting loop as in Figure 3a of the main text), in the regime of zero applied flux and negligible loop inductance.
L000393	
L000394	\subsection{Circuit model}
L000395	We consider a dc SQUID with two Josephson branches (labeled $j=1,2$), biased by a total current $I_b$. The gauge-invariant phase drops across the two branches are denoted by $\varphi_1(t_{\rm phys})$ and $\varphi_2(t_{\rm phys})$, and the voltages satisfy the Josephson relations
L000396	\begin{equation}
L000397	V_j(t_{\rm phys})=\frac{\Phi_0}{2\pi}\,\dot\varphi_j(t_{\rm phys}),
L000398	\qquad j=1,2,
L000399	\label{eq:JJ_voltage}
L000400	\end{equation}
L000401	where dot here means $d/dt_{\rm phys}$ with non-dimesionless time $t_{\rm phys}$ and $\Phi_0$ is the flux quantum.
L000402	
L000403	Each branch is modeled by an RCSJ element with capacitance $C_j$ and shunt
L000404	resistance $R_j$, so that the branch current $I_j$ is
L000405	\begin{equation}
L000406	I_j
L000407	= C_j\frac{\Phi_0}{2\pi}\,\ddot\varphi_j
L000408	+ \frac{1}{R_j}\frac{\Phi_0}{2\pi}\,\dot\varphi_j
L000409	+ I_{s,j}(\varphi_j,t_{\rm phys}).
L000410	\label{eq:RCSJ_each}
L000411	\end{equation}
L000412	The total bias current splits between the two branches:
L000413	\begin{equation}
L000414	I_b = I_1+I_2.
L000415	\label{eq:Ib_split}
L000416	\end{equation}
L000417	
L000418	To obtain Eq.~\eqref{eq:EOM_supp} one must assume that the total supercurrent contains two distinct sinusoidal channels: leg 1 is gate-modulated and has an ordinary CPR,
L000419	\begin{equation}
L000420	I_{s,1}(\varphi_1,t_{\rm phys})
L000421	= I_{c,1}(t_{\rm phys})\,\sin\varphi_1,
L000422	\qquad
L000423	I_{c,1}(t_{\rm phys})
L000424	= I_{c,1}^{(0)} + \delta I_{c,1}\cos(\Omega t_{\rm phys}).
L000425	\label{eq:gate_mod_Ic}
L000426	\end{equation}
L000427	while leg 2 provides a static phase-shifted CPR,
L000428	\begin{equation}
L000429	I_{s,2}(\varphi_2)
L000430	= I_{c,t}\,\sin(\varphi_2+\phi),
L000431	\label{eq:phi_shift_CPR}
L000432	\end{equation}
L000433	with constant amplitude $I_{c,t}$ and a fixed offset $\phi$. This offset can represent, e.g., an anomalous ($\varphi_0$) junction or any
L000434	built-in phase bias mechanism producing $\sin(\varphi+\phi)$ even at $\Phi=0$.
L000435	
L000436	Without such a genuinely phase-shifted second channel, the second term would collapse into a renormalization of the coefficient of $\sin x$ and Eq.~\eqref{eq:EOM_supp} would not result as written.
L000437	
L000438	\subsection{Zero-flux constraint and single-phase reduction}
L000439	Fluxoid quantization in a dc SQUID gives the constraint
L000440	\begin{equation}
L000441	\varphi_1-\varphi_2
L000442	= \frac{2\pi}{\Phi_0}\Big(\Phi_{\rm ext}+L I_{\rm circ}\Big),
L000443	\label{eq:fluxoid}
L000444	\end{equation}
L000445	where $\Phi_{\rm ext}$ is the applied flux, $L$ is the loop inductance, and
L000446	$I_{\rm circ}$ is the circulating current.
L000447	In the regime used in the main text,
L000448	\begin{equation}
L000449	\Phi_{\rm ext}=0,
L000450	\qquad
L000451	L\to 0,
L000452	\label{eq:zero_flux_small_L}
L000453	\end{equation}
L000454	Eq.~\eqref{eq:fluxoid} enforces $\varphi_1=\varphi_2$.
L000455	We therefore introduce a single collective phase variable
L000456	\begin{equation}
L000457	x(t_{\rm phys}) \equiv \varphi_1(t_{\rm phys})=\varphi_2(t_{\rm phys}),
L000458	\label{eq:single_phase_def}
L000459	\end{equation}
L000460	which also implies a common voltage across both branches by
L000461	Eq.~\eqref{eq:JJ_voltage}.
L000462	
L000463	\subsection{Physical equation of motion for the collective phase}
L000464	Summing Eq.~\eqref{eq:RCSJ_each} over $j=1,2$, using
L000465	Eqs.~\eqref{eq:Ib_split}--\eqref{eq:single_phase_def}, we obtain
L000466	\begin{equation}
L000467	C_\Sigma\frac{\Phi_0}{2\pi}\,\ddot x
L000468	+\frac{1}{R_\Sigma}\frac{\Phi_0}{2\pi}\,\dot x
L000469	+\Big[I_{c,1}^{(0)}+\delta I_{c,1}\cos(\Omega t_{\rm phys})\Big]\sin x
L000470	+ I_{c,t}\sin(x+\phi)
L000471	= I_b,
L000472	\label{eq:phys_EOM}
L000473	\end{equation}
L000474	where the parallel combinations are
L000475	\begin{equation}
L000476	C_\Sigma \equiv C_1+C_2,
L000477	\qquad
L000478	\frac{1}{R_\Sigma}\equiv \frac{1}{R_1}+\frac{1}{R_2}.
L000479	\label{eq:Reff_Ceff}
L000480	\end{equation}
L000481	
L000482	\subsection{Dimensionless units and mapping to the effective phase equation of motion}
L000483	We now nondimensionalize Eq.~\eqref{eq:phys_EOM}.
L000484	Choose a reference current scale $I_0$ (in practice one may take
L000485	$I_0=I_{c,1}^{(0)}$, or any convenient constant current used throughout the
L000486	paper). Define the plasma frequency associated with $(I_0,C_\Sigma)$,
L000487	\begin{equation}
L000488	\omega_{p0}\equiv
L000489	\sqrt{\frac{2\pi I_0}{\Phi_0\,C_\Sigma}}.
L000490	\label{eq:wp0_def}
L000491	\end{equation}
L000492	Introduce the dimensionless time $t=\omega_{p0}t_{\rm phys}$, so that
L000493	$d/dt_{\rm phys}=\omega_{p0}\,d/dt$.
L000494	Define dimensionless parameters
L000495	\begin{equation}
L000496	\beta \equiv \frac{1}{R_\Sigma C_\Sigma \omega_{p0}},
L000497	\qquad
L000498	\omega\equiv \frac{\Omega}{\omega_{p0}},
L000499	\label{eq:beta_omega_def}
L000500	\end{equation}
L000501	and dimensionless currents
L000502	\begin{equation}
L000503	i_{\rm dc}\equiv \frac{I_{c,1}^{(0)}}{I_0},
L000504	\qquad
L000505	i_{\rm ac}\equiv \frac{\delta I_{c,1}}{I_0},
L000506	\qquad
L000507	i_{c,t}\equiv \frac{I_{c,t}}{I_0}.
L000508	\label{eq:dimensionless_Ic}
L000509	\end{equation}
L000510	Finally, to match the convention used in Eq.~\eqref{eq:EOM_supp} (and in the
L000511	numerical code, where the bias enters as $+\tfrac12 i_b$), we define
L000512	\begin{equation}
L000513	i_b \equiv \frac{2 I_b}{I_0}
L000514	\qquad \Longleftrightarrow \qquad
L000515	\frac{I_b}{I_0}=\frac12\,i_b.
L000516	\label{eq:ib_convention}
L000517	\end{equation}
L000518	Dividing Eq.~\eqref{eq:phys_EOM} by $I_0$ and rewriting in the dimensionless
L000519	time $t$ yields exactly
L000520	\begin{equation}
L000521	\ddot x + \beta \dot x
L000522	+ \big[i_{\mathrm{dc}}+i_{\mathrm{ac}}\cos(\omega t)\big]\sin x
L000523	+ i_{c,t} \sin(x+\phi)
L000524	= \frac{1}{2} i_b ,
L000525	\label{eq:EOM_final_supp}
L000526	\end{equation}
L000527	which is Eq.~\eqref{eq:EOM} of the main text.
L000528	
L000529	\subsection{Mechanical interpretation}
L000530	Equation~\eqref{eq:EOM_final_supp} can be viewed as a damped pendulum whose restoring torque has two components: a parametrically modulated torque $\propto [i_{\rm dc}+i_{\rm ac}\cos(\omega t)]\sin x$
L000531	stemming from the gate-controlled critical current in leg 1, and  an additional static phase-shifted restoring torque $i_{c,t}\sin(x+\phi)$ from leg 2. If $\phi=0$ (or if branch 2 had $I_{s,2}\propto \sin x$), then the two torques combine into a single effective coefficient multiplying $\sin x$, and the distinct symmetry-breaking structure used in the main text would be lost.
L000532	
L000533	
L000534	
L000535	\section{Reduction of a gated single-loop dc SQUID at finite applied flux to an Effective Parametrically Driven Pendulum Equation}
L000536	\label{sec:supp_singleloop_gate_flux}
L000537	
L000538	In this section we extend the single-loop reduction of Sec.~\ref{sec:supp_singleloop_gate} to the case of a nonzero applied flux $\Phi_{\rm ext}\neq 0$. We show that, in the same regime assumed in the main text (negligible loop inductance and a common voltage across the two junctions), the dynamics still reduces to a single collective phase variable. The only modification is that the phase shift entering the static channel
L000539	$i_{c,t}\sin(x+\phi)$ is renormalized by the applied flux.
L000540	
L000541	\subsection{Circuit model}
L000542	
L000543	We consider a standard dc SQUID: two Josephson branches $j=1,2$ in parallel, forming a superconducting loop and biased by a total current $I_b$. The gauge-invariant phase drops across the branches are
L000544	$\varphi_1(t_{\rm phys})$ and $\varphi_2(t_{\rm phys})$.
L000545	Each branch is modeled by an RCSJ element with capacitance $C_j$ and shuntresistance $R_j$,
L000546	\begin{equation}
L000547	I_j
L000548	= C_j\frac{\Phi_0}{2\pi}\,\ddot\varphi_j
L000549	+ \frac{1}{R_j}\frac{\Phi_0}{2\pi}\,\dot\varphi_j
L000550	+ I_{s,j}(\varphi_j,t_{\rm phys}),
L000551	\qquad j=1,2,
L000552	\label{eq:RCSJ_each_flux}
L000553	\end{equation}
L000554	and current conservation gives
L000555	\begin{equation}
L000556	I_b = I_1+I_2.
L000557	\label{eq:Ib_split_flux}
L000558	\end{equation}
L000559	The Josephson voltage relations are
L000560	\begin{equation}
L000561	V_j(t_{\rm phys})=\frac{\Phi_0}{2\pi}\,\dot\varphi_j(t_{\rm phys}),
L000562	\qquad j=1,2.
L000563	\label{eq:JJ_voltage_flux}
L000564	\end{equation}
L000565	
L000566	As in Sec.~\ref{sec:supp_singleloop_gate}, to obtain the effective equation
L000567	used in the main text we assume two distinct sinusoidal supercurrent channels:
L000568	\begin{align}
L000569	I_{s,1}(\varphi_1,t_{\rm phys})
L000570	&= I_{c,1}(t_{\rm phys})\,\sin\varphi_1,
L000571	\qquad
L000572	I_{c,1}(t_{\rm phys})
L000573	= I_{c,1}^{(0)} + \delta I_{c,1}\cos(\Omega t_{\rm phys}),
L000574	\label{eq:gate_mod_Ic_flux}
L000575	\\
L000576	I_{s,2}(\varphi_2)
L000577	&= I_{c,t}\,\sin(\varphi_2+\phi).
L000578	\label{eq:phi_shift_CPR_flux}
L000579	\end{align}
L000580	Here $\phi$ is a built-in phase offset of the second channel (e.g. a
L000581	$\varphi_0$-junction contribution or any microscopic mechanism producing $\sin(\varphi+\phi)$ at $\Phi=0$). Importantly, if leg 2 had the ordinary CPR $I_{s,2}\propto \sin\varphi_2$ (i.e. $\phi=0$ and no other phase-bias mechanism), then the two branches would not generate a distinct ``second channel'' in the single-phase reduction: they would simply renormalize the coefficient of $\sin x$. Thus, the appearance of a term $I_{c,t}\sin(x+\phi)$ in the final single-phase equation requires a genuinely phase-shifted contribution.
L000582	
L000583	\subsection{Fluxoid quantization and the small-inductance limit}
L000584	
L000585	The gauge-invariant phase difference around the loop is constrained by fluxoid
L000586	quantization,
L000587	\begin{equation}
L000588	\varphi_1-\varphi_2
L000589	= \frac{2\pi}{\Phi_0}\Big(\Phi_{\rm ext}+L I_{\rm circ}\Big),
L000590	\label{eq:fluxoid_general_flux}
L000591	\end{equation}
L000592	where $L$ is the loop inductance and $I_{\rm circ}$ is the circulating current.
L000593	In the regime assumed in the main paper and throughout this reduction,
L000594	\begin{equation}
L000595	L\to 0,
L000596	\qquad\text{so that}\qquad
L000597	\varphi_1-\varphi_2=\delta_\Phi,
L000598	\label{eq:fluxoid_L0_flux}
L000599	\end{equation}
L000600	with the flux-imposed phase bias
L000601	\begin{equation}
L000602	\delta_\Phi \equiv \frac{2\pi \Phi_{\rm ext}}{\Phi_0}.
L000603	\label{eq:deltaPhi_def}
L000604	\end{equation}
L000605	Equation~\eqref{eq:fluxoid_L0_flux} is algebraic: the applied flux fixes the difference $\varphi_1-\varphi_2$ at all times. Consequently, the two junction voltages are identical:
L000606	\begin{equation}
L000607	\dot\varphi_1-\dot\varphi_2=\frac{d}{dt_{\rm phys}}(\delta_\Phi)=0
L000608	\quad\Longrightarrow\quad
L000609	V_1(t_{\rm phys})=V_2(t_{\rm phys}),
L000610	\label{eq:common_voltage_flux}
L000611	\end{equation}
L000612	consistent with the parallel circuit topology.
L000613	
L000614	\subsection{Single-phase reduction at finite flux}
L000615	
L000616	To reduce the dynamics to a single variable, we choose the collective phase
L000617	to be one of the branch phases, for concreteness
L000618	\begin{equation}
L000619	x(t_{\rm phys}) \equiv \varphi_1(t_{\rm phys}).
L000620	\label{eq:x_def_flux}
L000621	\end{equation}
L000622	Then the second branch phase is fixed by the flux constraint
L000623	Eq.~\eqref{eq:fluxoid_L0_flux}:
L000624	\begin{equation}
L000625	\varphi_2(t_{\rm phys}) = \varphi_1(t_{\rm phys})-\delta_\Phi
L000626	= x(t_{\rm phys})-\delta_\Phi.
L000627	\label{eq:gamma2_in_terms_of_x_flux}
L000628	\end{equation}
L000629	Substituting Eq.~\eqref{eq:gamma2_in_terms_of_x_flux} into the supercurrent of
L000630	branch 2 gives
L000631	\begin{equation}
L000632	I_{s,2}(\varphi_2)
L000633	= I_{c,t}\sin(\varphi_2+\phi)
L000634	= I_{c,t}\sin\!\big(x+\phi-\delta_\Phi\big).
L000635	\label{eq:Is2_subst_flux}
L000636	\end{equation}
L000637	Thus, at finite flux the second channel retains the same functional form but
L000638	with an effective phase offset
L000639	\begin{equation}
L000640	\phi_{\rm eff} \equiv \phi-\delta_\Phi
L000641	= \phi - \frac{2\pi \Phi_{\rm ext}}{\Phi_0}.
L000642	\label{eq:phi_eff_def}
L000643	\end{equation}
L000644	
L000645	\subsection{Physical equation of motion for the collective phase}
L000646	
L000647	We now sum the two RCSJ equations~\eqref{eq:RCSJ_each_flux} over $j=1,2$ and use
L000648	Eqs.~\eqref{eq:Ib_split_flux}, \eqref{eq:x_def_flux},
L000649	\eqref{eq:gamma2_in_terms_of_x_flux}, and \eqref{eq:Is2_subst_flux}.
L000650	The capacitive and resistive terms combine into effective parallel parameters
L000651	\begin{equation}
L000652	C_\Sigma \equiv C_1+C_2,
L000653	\qquad
L000654	\frac{1}{R_\Sigma}\equiv \frac{1}{R_1}+\frac{1}{R_2}.
L000655	\label{eq:Reff_Ceff_flux}
L000656	\end{equation}
L000657	We obtain the physical-time equation for the single phase $x$:
L000658	\begin{equation}
L000659	C_\Sigma\frac{\Phi_0}{2\pi}\,\ddot x
L000660	+\frac{1}{R_\Sigma}\frac{\Phi_0}{2\pi}\,\dot x
L000661	+\Big[I_{c,1}^{(0)}+\delta I_{c,1}\cos(\Omega t_{\rm phys})\Big]\sin x
L000662	+ I_{c,t}\sin\!\big(x+\phi-\delta_\Phi\big)
L000663	= I_b,
L000664	\label{eq:phys_EOM_flux}
L000665	\end{equation}
L000666	where dots denote $d/dt_{\rm phys}$.
L000667	
L000668	Eq. ~\eqref{eq:phys_EOM_flux} is the finite-flux counterpart of
L000669	Eq.~\eqref{eq:phys_EOM} in Sec.~\ref{sec:supp_singleloop_gate}. It differs only by the replacement $\phi\to\phi-\delta_\Phi$.
L000670	
L000671	\subsection{Dimensionless units and mapping to the effective phase equation of motion}
L000672	
L000673	We nondimensionalize Eq.~\eqref{eq:phys_EOM_flux} using the same conventions as
L000674	in Sec.~\ref{sec:supp_singleloop_gate}.
L000675	Choose a reference current scale $I_0$ (e.g. $I_0=I_{c,1}^{(0)}$) and define the
L000676	reference plasma frequency
L000677	\begin{equation}
L000678	\omega_{p0}\equiv
L000679	\sqrt{\frac{2\pi I_0}{\Phi_0\,C_\Sigma}}.
L000680	\label{eq:wp0_def_flux}
L000681	\end{equation}
L000682	Introduce dimensionless time $t=\omega_{p0}t_{\rm phys}$ and parameters
L000683	\begin{equation}
L000684	\beta \equiv \frac{1}{R_\Sigma C_\Sigma \omega_{p0}},
L000685	\qquad
L000686	\omega\equiv \frac{\Omega}{\omega_{p0}}.
L000687	\label{eq:beta_omega_def_flux}
L000688	\end{equation}
L000689	Define dimensionless current amplitudes
L000690	\begin{equation}
L000691	i_{\rm dc}\equiv \frac{I_{c,1}^{(0)}}{I_0},
L000692	\qquad
L000693	i_{\rm ac}\equiv \frac{\delta I_{c,1}}{I_0},
L000694	\qquad
L000695	i_{c,t}\equiv \frac{I_{c,t}}{I_0},
L000696	\label{eq:dimensionless_Ic_flux}
L000697	\end{equation}
L000698	and the bias convention
L000699	\begin{equation}
L000700	i_b \equiv \frac{2 I_b}{I_0}
L000701	\qquad \Longleftrightarrow \qquad
L000702	\frac{I_b}{I_0}=\frac12\,i_b.
L000703	\label{eq:ib_convention_flux}
L000704	\end{equation}
L000705	Dividing Eq.~\eqref{eq:phys_EOM_flux} by $I_0$ and rewriting in dimensionless
L000706	time yields
L000707	\begin{equation}
L000708	\ddot x + \beta \dot x
L000709	+ \big[i_{\mathrm{dc}}+i_{\mathrm{ac}}\cos(\omega t)\big]\sin x
L000710	+ i_{c,t} \sin\!\big(x+\phi-\delta_\Phi\big)
L000711	= \frac{1}{2} i_b ,
L000712	\label{eq:EOM_final_supp_flux}
L000713	\end{equation}
L000714	where dots now denote $d/dt$ with $t=\omega_{p0}t_{\rm phys}$.
L000715	
L000716	Eq.~\eqref{eq:EOM_final_supp_flux} is therefore identical to
L000717	Eq.~\eqref{eq:EOM_supp} of the zero-flux case upon replacement
L000718	\begin{equation}
L000719	\phi \ \longrightarrow\ \phi_{\rm eff}\equiv \phi-\delta_\Phi
L000720	= \phi - \frac{2\pi \Phi_{\rm ext}}{\Phi_0}.
L000721	\label{eq:phi_to_phi_eff}
L000722	\end{equation}
L000723	In other words, a nonzero applied flux simply shifts the phase offset of the static channel.
L000724	
L000725	\subsection{Remarks on the validity of the single-phase reduction}
L000726	
L000727	The reduction to a single collective phase variable relies crucially on the small-inductance limit in Eq.~\eqref{eq:fluxoid_L0_flux}. If $L$ is not negligible, then Eq.~\eqref{eq:fluxoid_general_flux} contains the circulating current $I_{\rm circ}$ and the phase difference $\varphi_1-\varphi_2$ becomes a dynamical degree of freedom. In that case, one generally must work with
L000728	two coupled variables (for example, the sum and difference phases
L000729	$\varphi_\pm\equiv(\varphi_1\pm\varphi_2)/2$) rather than a single equation for $x$. Therefore, Eq.~\eqref{eq:EOM_final_supp_flux} should be viewed as controlled when the loop is sufficiently ``stiff'' (geometric flux bias dominates and the inductive back action is negligible).
L000730	
L000731	
L000732	
L000733	
L000734	\section{Reduction of the Double-Loop SQUID to an Effective
L000735	Parametrically Driven Pendulum Equation}
L000736	\label{sec:SM_reduction}
L000737	
L000738	
L000739	\subsection{Circuit model}
L000740	We consider the double-loop device shown in Fig.~3(b) of the main text.
L000741	Electrically, it is a two-terminal superconducting circuit connecting the same left and right superconducting electrodes by three parallel Josephson branches:
L000742	(i) an upper conventional Josephson junction (JJ), (ii) a middle ``anomalous'' (or ``topological'') JJ with an intrinsic phase shift $\phi$, and (iii) a lower conventional JJ. Two loops are formed between these branches and are threaded
L000743	by external magnetic fluxes $\Phi_1(t)$ and $\Phi_2(t)$ (see Fig.~3(b)).
L000744	
L000745	The purpose of this section is to derive, from the full multi-branch RCSJ description and the fluxoid constraints, a single effective phase equation of motion of the form
L000746	\begin{equation}
L000747	\ddot x + \beta \dot x
L000748	+ \big[i_{\mathrm{dc}}+i_{\mathrm{ac}}\cos(\omega t)\big]\sin x
L000749	+ i_{c,t}\,\sin(x+\phi)
L000750	= \frac{1}{2}\,i_b,
L000751	\label{eq:EOM_SM_target}
L000752	\end{equation}
L000753	which is Eq.~(1) in the main text. Here and below, overdots denote derivatives with respect to dimensionless time, and all currents are normalized by a convenient current scale $I_0$.
L000754	
L000755	\subsection{Gauge-invariant phase differences and Josephson relations}
L000756	\label{sec:SM_gaugephase}
L000757	Let $\varphi_j(t)$ denote the gauge-invariant phase difference across junction $j$ ($j=1,2,3$ corresponding to upper, middle, lower branches). It is defined as
L000758	\begin{equation}
L000759	\varphi_j(t) = \theta_L(t)-\theta_R(t)
L000760	-\frac{2\pi}{\Phi_0}\int_{\mathcal{C}_j}\mathbf{A}(\mathbf{r},t)\cdot d\mathbf{l},
L000761	\label{eq:SM_gaugeinv_phase}
L000762	\end{equation}
L000763	where $\theta_{L,R}$ are the superconducting phases of the left/right
L000764	electrodes, $\mathbf{A}$ is the vector potential, $\mathcal{C}_j$ is a contour
L000765	through the $j$th junction, and $\Phi_0=h/2e$ is the superconducting flux
L000766	quantum.
L000767	
L000768	The voltage across junction $j$ is related to $\varphi_j$ by the second Josephson
L000769	relation,
L000770	\begin{equation}
L000771	V_j(t)=\frac{\Phi_0}{2\pi}\,\frac{d\varphi_j}{dt_{\rm phys}},
L000772	\label{eq:SM_josephson_voltage}
L000773	\end{equation}
L000774	where $t_{\rm phys}$ is physical time. Since all three junctions connect the same two electrodes in parallel, they share the same two-terminal voltage
L000775	$V(t)$, hence
L000776	\begin{equation}
L000777	V_1(t)=V_2(t)=V_3(t)\equiv V(t)
L000778	\quad \Longrightarrow \quad
L000779	\dot\varphi_1=\dot\varphi_2=\dot\varphi_3
L000780	\ \ \text{(in physical time)}.
L000781	\label{eq:SM_commonV}
L000782	\end{equation}
L000783	Therefore, differences $\varphi_1-\varphi_2$ and $\varphi_2-\varphi_3$ are not
L000784	independent dynamical variables: they are (to leading order) fixed by loop
L000785	fluxoid constraints (up to $2\pi$ integers), as shown next.
L000786	
L000787	\subsection{Two-loop fluxoid quantization constraints}
L000788	\label{sec:SM_fluxoid}
L000789	We assume the standard ``small-inductance'' limit for each loop:
L000790	the geometric inductances are sufficiently small that self-induced flux is
L000791	negligible compared to the applied flux, so that the loop constraints are set
L000792	by the externally applied fluxes $\Phi_1(t)$ and $\Phi_2(t)$ alone.
L000793	
L000794	For each loop, fluxoid quantization gives a constraint for the sum of
L000795	gauge-invariant phase drops around the loop. For the upper loop (between
L000796	junctions 1 and 2, threaded by $\Phi_2$) and lower loop (between junctions 2 and
L000797	3, threaded by $\Phi_1$), one can write
L000798	\begin{align}
L000799	\varphi_1(t)-\varphi_2(t)
L000800	&= \frac{2\pi}{\Phi_0}\,\Phi_2(t) + 2\pi n_2,
L000801	\label{eq:SM_constraint_upper}
L000802	\\
L000803	\varphi_2(t)-\varphi_3(t)
L000804	&= \frac{2\pi}{\Phi_0}\,\Phi_1(t) + 2\pi n_1,
L000805	\label{eq:SM_constraint_lower}
L000806	\end{align}
L000807	where $n_{1,2}\in\mathbb{Z}$ label fluxoid branches. In what follows we absorb
L000808	$2\pi n_{1,2}$ into the definition of the phases and work on a fixed branch,
L000809	so that
L000810	\begin{equation}
L000811	\varphi_1-\varphi_2 = f_2(t),
L000812	\qquad
L000813	\varphi_2-\varphi_3 = f_1(t),
L000814	\qquad
L000815	f_j(t)\equiv\frac{2\pi}{\Phi_0}\,\Phi_j(t)\ \ (j=1,2).
L000816	\label{eq:SM_define_f}
L000817	\end{equation}
L000818	
L000819	A convenient choice is to take the middle-junction phase as the collective
L000820	coordinate,
L000821	\begin{equation}
L000822	x(t)\equiv \varphi_2(t).
L000823	\label{eq:SM_define_x}
L000824	\end{equation}
L000825	Then Eqs.~\eqref{eq:SM_define_f} imply
L000826	\begin{equation}
L000827	\varphi_1(t)=x(t)+f_2(t),
L000828	\qquad
L000829	\varphi_3(t)=x(t)-f_1(t).
L000830	\label{eq:SM_gamma123}
L000831	\end{equation}
L000832	Thus the full three-junction problem reduces to a single dynamical variable
L000833	$x(t)$, with the fluxes entering as externally controlled offsets.
L000834	
L000835	\subsection{RCSJ equations for the three branches and current conservation}
L000836	\label{sec:SM_RCSJ}
L000837	We model each branch by a resistively and capacitively shunted junction (RCSJ).
L000838	The total current through branch $j$ is
L000839	\begin{equation}
L000840	I_j
L000841	=
L000842	I_{c,j}\, \sin\big(\varphi_j+\delta_j\big)
L000843	+\frac{V}{R_j}
L000844	+C_j\,\frac{dV}{dt_{\rm phys}},
L000845	\label{eq:SM_RCSJ_general}
L000846	\end{equation}
L000847	where $I_{c,j}$ is the critical current, $R_j$ and $C_j$ are shunt resistance
L000848	and capacitance, and $\delta_j$ is a possible intrinsic phase shift.
L000849	For the two conventional junctions we set $\delta_1=\delta_3=0$, while for the
L000850	anomalous (middle) junction we set $\delta_2=\phi$:
L000851	\begin{equation}
L000852	\delta_1=\delta_3=0,
L000853	\qquad
L000854	\delta_2=\phi.
L000855	\label{eq:SM_delta}
L000856	\end{equation}
L000857	Using the common voltage relation \eqref{eq:SM_josephson_voltage}--\eqref{eq:SM_commonV},
L000858	\begin{equation}
L000859	V(t)=\frac{\Phi_0}{2\pi}\,\dot x(t)\quad\text{(physical time)},
L000860	\qquad
L000861	\frac{dV}{dt_{\rm phys}}=\frac{\Phi_0}{2\pi}\,\ddot x(t).
L000862	\label{eq:SM_V_in_terms_of_x}
L000863	\end{equation}
L000864	
L000865	The external bias current $I_b$ injected into the two-terminal device is
L000866	distributed among the three branches,
L000867	\begin{equation}
L000868	I_b(t)=I_1(t)+I_2(t)+I_3(t).
L000869	\label{eq:SM_current_conservation}
L000870	\end{equation}
L000871	Substituting \eqref{eq:SM_gamma123}--\eqref{eq:SM_V_in_terms_of_x} into the
L000872	branch currents \eqref{eq:SM_RCSJ_general} yields a closed equation for $x(t)$.
L000873	
L000874	\subsection{Symmetric outer junctions and effective ``parametric'' restoring term}
L000875	\label{sec:SM_parametric}
L000876	To obtain a compact effective equation, we assume that the upper and lower junctions are identical:
L000877	\begin{equation}
L000878	I_{c,1}=I_{c,3}\equiv I_{c0},
L000879	\qquad
L000880	R_1=R_3\equiv R_0,
L000881	\qquad
L000882	C_1=C_3\equiv C_0.
L000883	\label{eq:SM_identical_outer}
L000884	\end{equation}
L000885	We keep the middle junction parameters $(I_{c,t},R_t,C_t)$ distinct.
L000886	
L000887	Using \eqref{eq:SM_gamma123}, the superconducting currents are
L000888	\begin{align}
L000889	I_1^{(J)} &= I_{c0}\sin\big(x+f_2(t)\big),
L000890	\\
L000891	I_2^{(J)} &= I_{c,t}\sin\big(x+\phi\big),
L000892	\\
L000893	I_3^{(J)} &= I_{c0}\sin\big(x-f_1(t)\big).
L000894	\end{align}
L000895	Thus, the pair of conventional branches contributes
L000896	\begin{equation}
L000897	I_1^{(J)}+I_3^{(J)}
L000898	=
L000899	I_{c0}\sin(x+f_2)+I_{c0}\sin(x-f_1).
L000900	\label{eq:SM_pair_general}
L000901	\end{equation}
L000902	
L000903	A particularly important (and experimentally natural) operation mode is the symmetric flux drive in which the two loops are driven equally,
L000904	\begin{equation}
L000905	f_1(t)=f_2(t)\equiv f(t)
L000906	\quad \Longleftrightarrow \quad
L000907	\Phi_1(t)=\Phi_2(t).
L000908	\label{eq:SM_symmetric_drive}
L000909	\end{equation}
L000910	Then Eq.~\eqref{eq:SM_pair_general} simplifies by the trigonometric identity
L000911	$\sin(x+f)+\sin(x-f)=2\sin x\cos f$:
L000912	\begin{equation}
L000913	I_1^{(J)}+I_3^{(J)}
L000914	=
L000915	2I_{c0}\cos\big(f(t)\big)\,\sin x.
L000916	\label{eq:SM_pair_parametric_exact}
L000917	\end{equation}
L000918	Equation \eqref{eq:SM_pair_parametric_exact} explicitly shows that the
L000919	conventional pair acts as a restoring torque $\propto \sin x$ whose strength is controlled by the flux through the multiplicative factor $2I_{c0}\cos f(t)$, i.e.\ a parametric modulation of the effective ``gravity'' term in the pendulum analogy.
L000920	
L000921	We now implement a dc+ac flux protocol
L000922	\begin{equation}
L000923	f(t)=f_{\rm dc}+f_{\rm ac}\cos(\Omega t_{\rm phys}),
L000924	\label{eq:SM_flux_protocol}
L000925	\end{equation}
L000926	where $f_{\rm dc}=(2\pi/\Phi_0)\Phi_{\rm dc}$, and $f_{\rm ac}=(2\pi/\Phi_0)\Phi_{\rm ac}$
L000927	is the ac amplitude. In the weak-modulation regime $|f_{\rm ac}|\ll 1$, we expand
L000928	\begin{equation}
L000929	\cos f(t)
L000930	=
L000931	\cos f_{\rm dc}
L000932	-
L000933	f_{\rm ac}\sin f_{\rm dc}\cos(\Omega t_{\rm phys})
L000934	+O(f_{\rm ac}^2).
L000935	\label{eq:SM_cos_expand}
L000936	\end{equation}
L000937	Substituting \eqref{eq:SM_cos_expand} into \eqref{eq:SM_pair_parametric_exact} gives
L000938	\begin{equation}
L000939	I_1^{(J)}+I_3^{(J)}
L000940	\approx
L000941	\underbrace{2I_{c0}\cos f_{\rm dc}}_{\displaystyle I_{\rm dc}}\sin x
L000942	+
L000943	\underbrace{\big(-2I_{c0}f_{\rm ac}\sin f_{\rm dc}\big)}_{\displaystyle I_{\rm ac}}
L000944	\cos(\Omega t_{\rm phys})\,\sin x
L000945	\ +\ O(f_{\rm ac}^2).
L000946	\label{eq:SM_pair_parametric_expand}
L000947	\end{equation}
L000948	Hence the conventional pair indeed generates the structure
L000949	$\big[I_{\rm dc}+I_{\rm ac}\cos(\Omega t_{\rm phys})\big]\sin x$.
L000950	
L000951	The middle junction contributes the additional term
L000952	\begin{equation}
L000953	I_2^{(J)}=I_{c,t}\sin(x+\phi),
L000954	\label{eq:SM_anomalous_term}
L000955	\end{equation}
L000956	which can be viewed mechanically as a second restoring torque (or ``spring'')
L000957	whose equilibrium is shifted by $\phi$.
L000958	
L000959	\subsection{Effective inertial and damping terms}
L000960	\label{sec:SM_damping_inertia}
L000961	The dissipative (resistive) currents add because the branches are in parallel:
L000962	\begin{equation}
L000963	I^{(R)}= \frac{V}{R_0}+\frac{V}{R_t}+\frac{V}{R_0}
L000964	=
L000965	G_\Sigma\,V,
L000966	\qquad
L000967	G_\Sigma\equiv \frac{2}{R_0}+\frac{1}{R_t}.
L000968	\label{eq:SM_Gsum}
L000969	\end{equation}
L000970	Similarly, capacitive currents add:
L000971	\begin{equation}
L000972	I^{(C)}=
L000973	C_0\frac{dV}{dt_{\rm phys}}+C_t\frac{dV}{dt_{\rm phys}}+C_0\frac{dV}{dt_{\rm phys}}
L000974	=
L000975	C_\Sigma\,\frac{dV}{dt_{\rm phys}},
L000976	\qquad
L000977	C_\Sigma\equiv 2C_0+C_t.
L000978	\label{eq:SM_Csum}
L000979	\end{equation}
L000980	Using \eqref{eq:SM_V_in_terms_of_x}, these become
L000981	\begin{equation}
L000982	I^{(R)}=\frac{\Phi_0}{2\pi}G_\Sigma\,\dot x,
L000983	\qquad
L000984	I^{(C)}=\frac{\Phi_0}{2\pi}C_\Sigma\,\ddot x
L000985	\quad \text{(physical time)}.
L000986	\label{eq:SM_RC_in_x}
L000987	\end{equation}
L000988	
L000989	\subsection{Closed physical-time equation for $x(t)$}
L000990	\label{sec:SM_physical_equation}
L000991	Collecting all contributions, the current balance \eqref{eq:SM_current_conservation}
L000992	yields (to leading order in $f_{\rm ac}$)
L000993	\begin{align}
L000994	\frac{\Phi_0}{2\pi}C_\Sigma\,\ddot x
L000995	+\frac{\Phi_0}{2\pi}G_\Sigma\,\dot x
L000996	+\Big[I_{\rm dc}+I_{\rm ac}\cos(\Omega t_{\rm phys})\Big]\sin x
L000997	+I_{c,t}\sin(x+\phi)
L000998	= I_b,
L000999	\label{eq:SM_physical_x_equation}
L001000	\end{align}
L001001	where $I_{\rm dc}$ and $I_{\rm ac}$ are defined in \eqref{eq:SM_pair_parametric_expand}.
L001002	Equation \eqref{eq:SM_physical_x_equation} is the desired single-coordinate
L001003	description in physical units.
L001004	
L001005	\subsection{Dimensionless units and mapping to the effective phase equation of motion}
L001006	\label{sec:SM_nondim}
L001007	We now introduce a dimensionless time and currents to obtain the compact form used in the main text.
L001008	
L001009	
L001010	A natural current scale for the symmetric device is the sum of the two outer critical currents
L001011	\begin{equation}
L001012	I_0 \equiv 2I_{c0}.
L001013	\label{eq:SM_I0_def}
L001014	\end{equation}
L001015	We define a reference plasma frequency associated with the total capacitance $C_\Sigma$ and current scale $I_0$,
L001016	\begin{equation}
L001017	\omega_{p0}\equiv \sqrt{\frac{2\pi I_0}{\Phi_0 C_\Sigma}}.
L001018	\label{eq:SM_omega_p0}
L001019	\end{equation}
L001020	Introduce dimensionless time
L001021	\begin{equation}
L001022	t \equiv \omega_{p0}\,t_{\rm phys},
L001023	\label{eq:SM_dimless_time}
L001024	\end{equation}
L001025	so that $d/dt_{\rm phys}=\omega_{p0}\,d/dt$ and $d^2/dt_{\rm phys}^2=\omega_{p0}^2\,d^2/dt^2$.
L001026	
L001027	Define the dimensionless damping constant
L001028	\begin{equation}
L001029	\beta \equiv \frac{G_\Sigma}{C_\Sigma\,\omega_{p0}},
L001030	\label{eq:SM_beta_def}
L001031	\end{equation}
L001032	and the dimensionless drive frequency
L001033	\begin{equation}
L001034	\omega \equiv \frac{\Omega}{\omega_{p0}}.
L001035	\label{eq:SM_omega_def}
L001036	\end{equation}
L001037	
L001038	We normalize the effective dc and ac amplitudes by $I_0$:
L001039	\begin{equation}
L001040	i_{\rm dc}\equiv \frac{I_{\rm dc}}{I_0},
L001041	\qquad
L001042	i_{\rm ac}\equiv \frac{I_{\rm ac}}{I_0},
L001043	\qquad
L001044	i_{c,t}\equiv \frac{I_{c,t}}{I_0}.
L001045	\label{eq:SM_idc_iac_ict_def}
L001046	\end{equation}
L001047	Finally, the normalized bias current entering Eq.~\eqref{eq:SM_physical_x_equation} is
L001048	\begin{equation}
L001049	i_b^{(0)}\equiv \frac{I_b}{I_0}.
L001050	\label{eq:SM_ib0_def}
L001051	\end{equation}
L001052	
L001053	\paragraph*{Dimensionless equation.}
L001054	Dividing Eq.~\eqref{eq:SM_physical_x_equation} by $I_0$ and using the above
L001055	definitions, we obtain
L001056	\begin{equation}
L001057	\ddot x + \beta \dot x
L001058	+ \big[i_{\rm dc}+i_{\rm ac}\cos(\omega t)\big]\sin x
L001059	+ i_{c,t}\sin(x+\phi)
L001060	= i_b^{(0)}.
L001061	\label{eq:SM_dimless_equation}
L001062	\end{equation}
L001063	
L001064	In some conventions, one defines the plotted bias current as
L001065	$i_b \equiv I_b/I_{c0}$, i.e.\ normalized by a single outer junction
L001066	critical current. Since $I_0=2I_{c0}$, we then have
L001067	\begin{equation}
L001068	i_b^{(0)}=\frac{I_b}{I_0}=\frac{I_b}{2I_{c0}}=\frac{1}{2}\,\frac{I_b}{I_{c0}}
L001069	=\frac{1}{2}\,i_b.
L001070	\label{eq:SM_half_factor}
L001071	\end{equation}
L001072	Substituting \eqref{eq:SM_half_factor} into \eqref{eq:SM_dimless_equation}
L001073	reproduces exactly Eq.~\eqref{eq:EOM_SM_target} used in the main text.
L001074	
L001075	\subsection{Remarks on validity and generalizations}
L001076	\label{sec:SM_validity}
L001077	
L001078	The reduction \eqref{eq:SM_constraint_upper}--\eqref{eq:SM_gamma123} assumes negligible loop self-inductances. If inductances are not negligible, then the fluxoid constraints acquire additional terms proportional to circulating currents, and $f_1,f_2$ become coupled to the dynamics. In that case one must solve a larger set of equations (phases plus loop currents). The present limit is appropriate for sufficiently small loops or sufficiently weak circulating
L001079	currents.
L001080	
L001081	
L001082	The clean parametric form \eqref{eq:SM_pair_parametric_exact} arises for $f_1(t)=f_2(t)$. If $f_1\neq f_2$, the conventional pair yields
L001083	$\sin(x+f_2)+\sin(x-f_1)$, which can be rewritten as a combination of $\sin x$ and $\cos x$ with time-dependent coefficients. This leads to a more general effective CPR containing both first-harmonic sine and cosine terms. The symmetric protocol is the simplest route to the compact form used in the main text.
L001084	
L001085	
L001086	The identification of $i_{\rm dc}$ and $i_{\rm ac}$ via \eqref{eq:SM_pair_parametric_expand} assumes $|f_{\rm ac}|\ll 1$. For larger $f_{\rm ac}$, higher harmonics in $\cos f(t)$ appear and generate additional time-dependent terms (including higher Fourier components), which can be kept systematically if needed.
L001087	
L001088	
L001089	Eq. \eqref{eq:EOM_SM_target} is mechanically equivalent to a damped pendulum with a gravitational torque whose strength is modulated in time, $\propto [i_{\rm dc}+i_{\rm ac}\cos(\omega t)]\sin x$, and an additional phase-shifted restoring torque $i_{c,t}\sin(x+\phi)$, which acts like a second torsional spring with equilibrium rotated by $\phi$.
L001090	
L001091	
L001092	\section{Kapitza averaging with AC current: derivation of the effective CPR and frequency-dependent rectification amplitude $\eta(\omega)$}
L001093	
L001094	We start from the driven equation of motion
L001095	\begin{equation}
L001096	\ddot x + \beta \dot x
L001097	+ \big[i_{\mathrm{dc}}+i_{\mathrm{ac}}\cos(\omega t)\big]\sin x
L001098	+ i_{c,t}\sin(x+\phi)
L001099	= \frac{1}{2}i_b .
L001100	\label{eq:EOM}
L001101	\end{equation}
L001102	Following the Kapitza ideology, we decompose
L001103	\begin{equation}
L001104	x(t)=X(t)+\xi(t),
L001105	\end{equation}
L001106	where $X(t)$ is slow and $\xi(t)$ is a small fast correction, $|\xi|\ll 1$.
L001107	Expanding Eq.~\eqref{eq:EOM} up to $O(\xi^2)$ gives
L001108	\begin{align}
L001109	\ddot X+\ddot \xi + \beta(\dot X+\dot \xi)
L001110	&+ \big[i_{\mathrm{dc}}+i_{\mathrm{ac}}\cos(\omega t)\big]
L001111	\Big(\sin X + \xi \cos X -\tfrac{1}{2}\xi^2\sin X\Big)
L001112	\nonumber\\
L001113	&+ i_{c,t}\Big(\sin(X+\phi)+\xi\cos(X+\phi)-\tfrac{1}{2}\xi^2\sin(X+\phi)\Big)
L001114	=\frac{1}{2}i_b.
L001115	\label{eq:expanded2}
L001116	\end{align}
L001117	
L001118	On the fast time scale, we neglect $\ddot X$ and $\dot X$ and retain the terms
L001119	linear in $\xi$ and proportional to the oscillatory part
L001120	$\delta c(t)\equiv i_{\mathrm{ac}}\cos(\omega t)$. This yields
L001121	\begin{equation}
L001122	\ddot \xi + \beta \dot \xi + \omega_0^2(X)\,\xi
L001123	\simeq
L001124	-i_{\mathrm{ac}}\cos(\omega t)\,\sin X,
L001125	\label{eq:xi-eq-corr}
L001126	\end{equation}
L001127	where
L001128	\begin{equation}
L001129	\omega_0^2(X)\equiv i_{\mathrm{dc}}\cos X + i_{c,t}\cos(X+\phi).
L001130	\label{eq:omega0}
L001131	\end{equation}
L001132	The steady periodic solution of Eq.~\eqref{eq:xi-eq-corr} can be written as
L001133	\begin{equation}
L001134	\xi(t)=\Re\!\left[\tilde\xi\,e^{i\omega t}\right],
L001135	\qquad
L001136	\tilde\xi=
L001137	-\frac{i_{\mathrm{ac}}\sin X}{\omega_0^2(X)-\omega^2+i\beta\omega}.
L001138	\label{eq:xi-sol-corr}
L001139	\end{equation}
L001140	Hence, the relevant time averages are
L001141	\begin{align}
L001142	\langle \xi\rangle_t &= 0,
L001143	\qquad
L001144	\langle \xi^2\rangle_t = \frac{|\tilde\xi|^2}{2}
L001145	=
L001146	\frac{i_{\mathrm{ac}}^2\sin^2 X}{2D(X,\omega)},
L001147	\label{eq:xi2-corr}
L001148	\\
L001149	\Big\langle \cos(\omega t)\,\xi(t)\Big\rangle_t
L001150	&=\frac{1}{2}\Re(\tilde\xi)
L001151	=
L001152	-\frac{i_{\mathrm{ac}}\sin X}{2}\,
L001153	\frac{\omega_0^2(X)-\omega^2}{D(X,\omega)},
L001154	\label{eq:cosxi-corr}
L001155	\end{align}
L001156	with the standard Lorentzian denominator
L001157	\begin{equation}
L001158	D(X,\omega)\equiv \big(\omega_0^2(X)-\omega^2\big)^2+(\beta\omega)^2.
L001159	\label{eq:Ddef}
L001160	\end{equation}
L001161	
L001162	Averaging Eq.~\eqref{eq:expanded2} over the fast oscillations and keeping all
L001163	terms up to $O(i_{\mathrm{ac}}^2)$, we obtain
L001164	\begin{align}
L001165	\ddot X + \beta \dot X
L001166	&+ i_{\mathrm{dc}}\sin X + i_{c,t}\sin(X+\phi)
L001167	\nonumber\\
L001168	&\underbrace{+\ i_{\mathrm{ac}}\cos X\Big\langle \cos(\omega t)\,\xi(t)\Big\rangle_t}_{\text{cross term }O(i_{\mathrm{ac}}^2)}
L001169	\underbrace{-\ \frac{1}{2}\langle\xi^2\rangle_t\Big[i_{\mathrm{dc}}\sin X+i_c\sin(X+\phi)\Big]}_{O(i_{\mathrm{ac}}^2)}
L001170	=\frac{1}{2}I_b.
L001171	\label{eq:slow-corr}
L001172	\end{align}
L001173	The second line contains two distinct $O(\Phi_{\mathrm{ac}}^2)$ contributions. Importantly, the cross term survives at the unmodulated equilibrium and must be retained for a consistent Kapitza reduction.
L001174	
L001175	For the diode effect we focus on the vicinity of the static equilibrium
L001176	$x_0$ at zero bias (or small $I_b$), defined by the unmodulated CPR
L001177	\begin{equation}
L001178	i_{\mathrm{dc}}\sin x_0+i_c\sin(x_0+\phi)=0,
L001179	\qquad
L001180	x_0=\operatorname{atan2}\!\big(-i_{c,t}\sin\phi,\ i_{\mathrm{dc}}+i_{c,t}\cos\phi\big).
L001181	\label{eq:x0}
L001182	\end{equation}
L001183	Near equilibrium $x_0$, the contribution is proportional to
L001184	$\langle\xi^2\rangle_t[\Phi_{\mathrm{dc}}\sin X+i_c\sin(X+\phi)]$
L001185	is proportional to the unmodulated force and thus vanishes at $X=x_0$.
L001186	The leading symmetry-breaking $O(\Phi_{\mathrm{ac}}^2)$ correction therefore originates from the cross term. Using Eq.~\eqref{eq:cosxi-corr} and $\sin X\cos X=\tfrac12\sin2X$,
L001187	we can encode the averaged dynamics in an effective static CPR
L001188	\begin{equation}
L001189	I_s^{\mathrm{eff}}(X)=A_1\sin X+B_1\cos X + A_2(\omega)\,\sin 2X,
L001190	\label{eq:CPR-eff}
L001191	\end{equation}
L001192	with
L001193	\begin{equation}
L001194	A_1=i_{\mathrm{dc}}+i_{c,t}\cos\phi,\qquad B_1=i_{c,t}\sin\phi,
L001195	\label{eq:A1B1}
L001196	\end{equation}
L001197	Approximating the slowly varying prefactor
L001198	$[\omega_0^2(X)-\omega^2]/D(X,\omega)$ by its value at $X=x_0$, we obtain
L001199	\begin{equation}
L001200	A_2(\omega)=
L001201	-\frac{i_{\mathrm{ac}}^2}{4}\,
L001202	\frac{\omega_0^2(x_0)-\omega^2}{\big(\omega_0^2(x_0)-\omega^2\big)^2+(\beta\omega)^2}.
L001203	\label{eq:A2-corr}
L001204	\end{equation}
L001205	Introducing
L001206	\begin{equation}
L001207	Q=\sqrt{A_1^2+B_1^2},\qquad \delta = \arctan\!\frac{B_1}{A_1},
L001208	\label{eq:Rdelta}
L001209	\end{equation}
L001210	the first harmonic becomes $Q\sin(X+\delta)$.
L001211	
L001212	
L001213	For $|A_2|\ll R$, the extrema of
L001214	$I_s^{\mathrm{eff}}(X)=Q\sin(X+\delta)+A_2\sin2X$ give
L001215	\begin{equation}
L001216	I_c^+ \approx Q + A_2(\omega)\,\sin(2\delta),
L001217	\qquad
L001218	I_c^- \approx -Q + A_2(\omega)\,\sin(2\delta),
L001219	\label{eq:Icpm-corr}
L001220	\end{equation}
L001221	and therefore the diode efficiency;
L001222	\begin{equation}
L001223	\eta(\omega)=\frac{I_c^+-|I_c^-|}{I_c^+ + |I_c^-|}
L001224	\approx
L001225	\frac{A_2(\omega)}{Q}\,\sin(2\delta).
L001226	\label{eq:eta-gen-corr}
L001227	\end{equation}
L001228	Substituting Eq.~\eqref{eq:A2-corr} finally yields the corrected analytic
L001229	frequency dependence
L001230	\begin{equation}
L001231	\eta(\omega)
L001232	\;\approx\;
L001233	-\frac{i_{\mathrm{ac}}^2}{4R}\,
L001234	\frac{\omega_0^2(x_0)-\omega^2}
L001235	     {\big[\omega_0^2(x_0)-\omega^2\big]^2+(\beta\omega)^2}
L001236	\,\sin 2\delta
L001237	\label{eq:eta-final-correct}
L001238	\end{equation}
L001239	with
L001240	\begin{equation}
L001241	\omega_0^2(x_0)=i_{\mathrm{dc}}\cos x_0 + i_{c,t}\cos(x_0+\phi),
L001242	\end{equation}
L001243	and $x_0,Q,\delta$ given in Eqs.~\eqref{eq:x0} and \eqref{eq:Rdelta}.
